function openForm(kind,id){if(!revealed()||!schemas[kind]&&kind!=='settings')return;const form=root.querySelector('[data-pa-form="'+kind+'"]'),box=form?.closest('details');if(!form)return;box.open=true;openForms[kind]=true;form.reset();delete drafts[kind];const record=id?plan[kind].find(r=>r.id===id):kind==='settings'?C.scoped(plan.settings,filter)[0]:null;expected[kind]=record?JSON.parse(JSON.stringify(record)):null;form.dataset.editId=record?.id||'';if(record){for(const field of form.elements){if(!field.name)continue;if(field.type==='checkbox')field.checked=(record[field.name]||[]).includes(field.value);else{const def=schemas[kind]?.fields.find(f=>f[0]===field.name),value=record[field.name];field.value=value==null?'':def?.[2]==='money'?value/100:value;}}}else{const d=form.querySelector('[name="date"]'),month=form.querySelector('[name="month"]');if(d)d.value=today();if(month)month.value=filter.from.slice(0,7);}box.scrollIntoView({behavior:'smooth',block:'start'});form.querySelector('input,select')?.focus();}
function moneyInput(form,name,optional=false){const value=form.get(name);if(value==null||String(value).trim()===''){if(optional)return null;throw Error('Preencha os valores obrigatórios; zero deve ser informado explicitamente.');}const n=Number(value),c=Math.round(n*100);if(!Number.isFinite(n)||!Number.isSafeInteger(c))throw Error('Valor monetário inválido.');return c;}
